let SFO;function sfxCt(r){r.querySelectorAll("[data-to]").forEach(n=>{const t=+n.dataset.to,s=performance.now(),f=now=>{const p=Math.min(1,(now-s)/1600);n.textContent=Math.round(t*(1-Math.pow(1-p,3))).toLocaleString("pt-BR");if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)})}
function sfxInit(){const rm=document.getElementById("rm");if(rm){let u="";try{u=localStorage.getItem("pf_ru")||""}catch(e){}if(u){document.getElementById("au").value=u;rm.checked=true;let pw="";try{pw=localStorage.getItem("pf_rp")||""}catch(e){}if(pw)document.getElementById("ap").value=pw}rm.onchange=()=>{if(!rm.checked){try{localStorage.removeItem("pf_ru");localStorage.removeItem("pf_rp")}catch(e){}}};}const gg=document.getElementById("sfx-gg");if(gg)gg.onclick=()=>toast("Login com o Google ainda não está disponível. Use usuário e senha.","err");SFO&&SFO.disconnect();const els=document.querySelectorAll(".sfx-r"),b=document.getElementById("sfx-top");if(b)b.onclick=()=>{scrollTo({top:0,behavior:"smooth"});setTimeout(()=>{const a=document.getElementById("au");a&&a.focus()},500)};if(!("IntersectionObserver"in window)){els.forEach(e=>{e.classList.add("in");sfxCt(e)});return}SFO=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");sfxCt(x.target);SFO.unobserve(x.target)}}),{threshold:.25});els.forEach(e=>SFO.observe(e))}

