 const tcP=()=>{const v=$("tc").value,c=TC.find(x=>x[0]===v)||TC[0];$("tct").innerHTML=`${tgl(c)}<span class="dn2">${c[0]}</span><i class="cv">${CH}</i>`;$("tcl").innerHTML=TC.map(x=>`<button type="button" class="di${x[0]===v?" sel2":""}" data-v="${x[0]}">${tgl(x)}<span>${x[0]}</span></button>`).join("")};
 tcP();$("tct").onclick=()=>$("tcd").classList.toggle("open");
 $("tcl").onclick=e=>{const b=e.target.closest(".di");if(!b)return;$("tc").value=b.dataset.v;$("tcd").classList.remove("open");tcP()};
 const put=(e,h)=>{if(e.dataset.h!==h){e.innerHTML=h;e.dataset.h=h}};
 const tkSt=l=>{const a=l.filter(t=>t.st==="Aberto").length;$("tks").innerHTML=[["msg","Total de tickets",l.length],["bell","Em andamento",a],["check","Fechados",l.length-a]].map(([ic,t,v])=>`<div class='rf-sc'><i>${I(ic)}</i><div><small>${t}</small><b>${v}</b></div></div>`).join("");$("tkn").textContent=l.length};const cur=()=>u.tickets.find(t=>t.id===tkSel);
 const bubOld=t=>tkMsgs(t).map(r=>`<div class="tkc-b${r.w==='u'?' me':''}">${r.w==='s'?`<b>${E(r.a)}</b>`:''}<p>${E(r.m)}</p><small>${tf(r.t)}</small></div>`).join('')+((t.rs&&t.rs.length)?'':`<div class="tkc-n">Recebemos seu ticket. O suporte responde por aqui em breve.</div>`);
 const tkTm=x=>new Date(x).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"}),tkDy=x=>{const d=new Date(x);return d.toDateString()===new Date().toDateString()?"Hoje":d.toDateString()===new Date(Date.now()-864e5).toDateString()?"Ontem":d.toLocaleDateString("pt-BR")};
const bub=t=>{let last="",h="";tkMsgs(t).forEach(r=>{const dy=tkDy(r.t),me=r.w==="u";if(dy!==last){last=dy;h+=`<div class="tkv-dv"><span>${dy}</span></div>`}h+=`<div class="tkv-r${me?" me":""}"><div class="tkv-n"><b>${me?"Você":E(r.a)}</b><small>${tkTm(r.t)}</small></div><div class="tkv-b">${(r.im||[]).map(s=>`<img class="tkv-im" src="${s}" alt="Imagem enviada">`).join("")}${r.m?`<p>${E(r.m)}</p>`:""}</div></div>`});if(!(t.rs&&t.rs.length))h+=`<div class="tkc-n">Recebemos seu ticket. O suporte responde por aqui em breve.</div>`;return h};
const tkShell=t=>{tkPend=null;return `<div class="tkv"><div class="tkv-h"><button type="button" class="tkv-bk" id="tkx"><svg viewBox="0 0 24 24"><path d="M15 6l-6 6 6 6"/></svg>Atendimentos</button><span class="tkv-sep"></span><i class="tkv-ic"><svg viewBox="0 0 24 24"><path d="M21 12a8 8 0 0 1-11.500 7.200L4 20l1-4.500A8 8 0 1 1 21 12z"/></svg></i><div class="tkv-t"><b>${E(t.s)}</b><small><strong>#${t.id}</strong><em class="tkv-cat">${E(t.c)}</em><span>Aberto em ${new Date(t.t).toLocaleDateString("pt-BR")}</span></small></div><span class="b" id="tkb"></span><button type="button" class="sm" id="tkc">Fechar ticket</button></div><div class="tkv-m" id="tkm"></div><div class="tkv-pv" id="tkpv" hidden></div><div class="tkv-f"><input type="file" id="tkf" accept="image/*" hidden><button type="button" class="tkv-at" id="tkat" aria-label="Anexar imagem"><svg viewBox="0 0 24 24"><path d="M21 11.500l-8.500 8.500a5 5 0 0 1-7-7l9-9a3.300 3.300 0 0 1 4.700 4.700l-9 9a1.700 1.700 0 0 1-2.400-2.400l8-8"/></svg></button><textarea id="tkr" rows="1" maxlength="1000"></textarea><button type="button" class="tkv-sd" id="tksn" aria-label="Enviar"><svg viewBox="0 0 24 24"><path d="M21 3L3 11l6 2 2 6 3-4 5 4z"/></svg></button></div></div>`};
const tkPv=()=>{const p=$("tkpv");if(!p)return;if(tkPend){p.hidden=false;p.innerHTML=`<img src="${tkPend}" alt=""><button type="button" id="tkpx" aria-label="Remover imagem">×</button>`}else{p.hidden=true;p.innerHTML=""}};
const tkPick=i=>{const f=i.files&&i.files[0];i.value="";if(!f)return;if(!/^image\//.test(f.type))return toast("Envie um arquivo de imagem","err");const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,900/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);tkPend=c.toDataURL("image/jpeg",.72);tkPv()};im.onerror=()=>toast("Não foi possível ler a imagem","err");im.src=r.result};r.readAsDataURL(f)};
const tkLb=s=>{const o=document.createElement("div");o.className="tkv-lb";o.innerHTML=`<img src="${s}" alt="">`;o.onclick=()=>o.remove();document.body.appendChild(o)};
const lst=()=>{tkPurge();const l=[...u.tickets].reverse();tkSt(l);put($("tl"),l.length?l.map(t=>{const ms=tkMsgs(t),lm=ms[ms.length-1];return`<div class="card tk tk-c${t.id===tkSel?' on':''}" data-id="${t.id}"><h4>${E(t.s)}<span class="b ${t.st==="Aberto"?"c":"x"}">${t.st==="Aberto"?"Em andamento":t.st}</span></h4><small>#${t.id} · ${E(t.c)} · ${tf(t.t)}</small><p class="tk-pv">${lm.w==='s'?'Suporte: ':lm.i?'':'Você: '}${E(lm.m)}</p><div class="tk-ac"><button class="sm" data-o="${t.id}">${t.id===tkSel?'Chat aberto':'Abrir chat'}</button>${t.st==="Aberto"?`<button class="sm" data-c="${t.id}">Fechar ticket</button>`:""}</div></div>`}).join(""):`<div class="card em">${I("msg")}<p>Nenhum ticket ainda.</p></div>`);tbadge()};
 const pan=sc=>{const w=$("tcw");if(tkSel&&!cur())tkSel=null;const t=cur();$("tgw").classList.toggle("tc",!!t);
  if(!t){w.hidden=true;w.dataset.k="";w.innerHTML="";return}
  let fr=false;
  if(w.dataset.k!==String(tkSel)){fr=true;w.hidden=false;w.dataset.k=String(tkSel);w.innerHTML=tkShell(t)||`<div class="tkc"><div class="tkc-h"><div><b>${E(t.s)}</b><small>#${t.id} · ${E(t.c)}</small></div><span class="b" id="tkb"></span><button type="button" class="sm" id="tkc">Fechar ticket</button><button type="button" class="tkc-x" id="tkx" aria-label="Fechar chat">×</button></div><div class="tkc-m" id="tkm"></div><div class="tkc-f"><textarea id="tkr" rows="2" maxlength="1000"></textarea><button type="button" class="go" id="tks">Enviar</button></div></div>`}
  const m=$("tkm"),near=fr||m.scrollHeight-m.scrollTop-m.clientHeight<60;
  put(m,bub(t));if(near)m.scrollTop=m.scrollHeight;
  const b=$("tkb");b.className="b "+(t.st==="Aberto"?"c":"x");b.textContent=t.st==="Aberto"?"Em andamento":t.st;$("tkc").hidden=t.st!=="Aberto";
  const ta=$("tkr"),on=t.st==="Aberto";ta.disabled=!on;$("tksn").disabled=!on;$("tkat").disabled=!on;ta.placeholder=on?"Escreva sua mensagem… (Enter envia)":"Ticket fechado. Abra um novo ticket se precisar.";
  if(sc&&innerWidth<=1250)w.scrollIntoView({behavior:"smooth",block:"start"});else if(sc&&on)ta.focus()};
 const snd=()=>{const t=cur(),ta=$("tkr");if(!t||t.st!=="Aberto"||!ta)return;const m=ta.value.trim();if(!m&&!tkPend)return;const o={m,t:Date.now()};if(tkPend){o.im=[tkPend];tkPend=null;tkPv()}(t.us=t.us||[]).push(o);save();ta.value="";lst();pan();const k=$("tkm");k.scrollTop=k.scrollHeight;ta.focus()};
 lst();
