const phN=x=>{const d=String(x||'').replace(/\D/g,'');return d.length>11&&d.startsWith('55')?d.slice(2):d.slice(0,11)};
const phF=d=>{if(d.length<=2)return d?`(${d}`:'';const r=d.slice(2),k=r.length>8?5:4;return `(${d.slice(0,2)}) ${r.slice(0,k)}${r.length>k?'-'+r.slice(k):''}`};
const phOk=d=>(d.length===10||d.length===11)&&+d.slice(0,2)>=11&&(d.length===10||d[2]==='9');
const phM=d=>d?`+55 (${d.slice(0,2)}) ${'•'.repeat(d.length>10?5:4)}-${d.slice(-4)}`:'Não cadastrado';;
