function eyeUp(ids){ids.forEach(id=>{const i=$(id);if(!i||i.dataset.eye)return;i.dataset.eye=1;const w=document.createElement('div');w.style.cssText='position:relative';i.parentNode.insertBefore(w,i);w.appendChild(i);i.style.paddingRight='46px';const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Mostrar senha');b.style.cssText='position:absolute;right:6px;top:50%;transform:translateY(-50%);width:36px;height:36px;display:grid;place-items:center;background:none;border:0;color:var(--mut);cursor:pointer;border-radius:8px;padding:0';const sv=off=>`<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${off?'<path d="M17.94 17.94A10.9 10.9 0 0 1 12 20c-7 0-11-8-11-8a19.8 19.8 0 0 1 5.06-5.94M9.9 4.24A10.9 10.9 0 0 1 12 4c7 0 11 8 11 8a19.8 19.8 0 0 1-3.17 4.19M14.12 14.12a3 3 0 1 1-4.24-4.24M1 1l22 22"/>':'<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>'}</svg>`;b.innerHTML=sv(0);b.onclick=()=>{const sh=i.type==='password';i.type=sh?'text':'password';b.innerHTML=sv(sh);b.setAttribute('aria-label',sh?'Ocultar senha':'Mostrar senha');i.focus()};w.appendChild(b)})}
const B32='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function b32e(b){let o='',bits=0,v=0;for(const x of b){v=(v<<8)|x;bits+=8;while(bits>=5){o+=B32[(v>>>(bits-5))&31];bits-=5}v&=(1<<bits)-1}if(bits>0)o+=B32[(v<<(5-bits))&31];return o}
function b32d(s){let bits=0,v=0;const o=[];for(const c of s){const i=B32.indexOf(c);if(i<0)continue;v=(v<<5)|i;bits+=5;if(bits>=8){o.push((v>>>(bits-8))&255);bits-=8}v&=(1<<bits)-1}return new Uint8Array(o)}
async function totp(sec,t){const c=Math.floor((t||Date.now())/30000);const k=await crypto.subtle.importKey('raw',b32d(sec),{name:'HMAC',hash:'SHA-1'},false,['sign']);const b=new ArrayBuffer(8),dv=new DataView(b);dv.setUint32(0,Math.floor(c/4294967296));dv.setUint32(4,c>>>0);const h=new Uint8Array(await crypto.subtle.sign('HMAC',k,b));const o=h[19]&15;const n=(((h[o]&127)<<24)|(h[o+1]<<16)|(h[o+2]<<8)|h[o+3])%1000000;return String(n).padStart(6,'0')}
async function totpOk(sec,code){code=String(code).trim();try{for(const d of[-2,-1,0,1,2]){if(await totp(sec,Date.now()+d*30000)===code)return true}}catch(e){}return false}
function totpSetup(u,done){const nm=String(SN()).replace(/<[^>]*>/g,'');const sec=b32e(crypto.getRandomValues(new Uint8Array(20)));const tag=b32e(crypto.getRandomValues(new Uint8Array(3))).slice(0,4);const uri='otpauth://totp/'+encodeURIComponent(nm+':'+u.n)+'?secret='+sec+'&issuer='+encodeURIComponent(nm)+'&algorithm=SHA1&digits=6&period=30';
 const o=mdl(`<h3>Configurar autenticador</h3><p class='mu'>1. No app <b>Google Authenticator</b>, toque em <b>+</b> e escolha <b>Ler código QR</b>. A conta vai aparecer no app como <b>${E(nm)} (${E(u.n)})</b>. Se você já adicionou outra com o mesmo nome antes, apague a antiga para não confundir.</p><div style='display:grid;place-items:center;margin:10px 0'><div id='tq' style='background:#fff;padding:10px;border-radius:12px;min-width:120px;min-height:120px;display:grid;place-items:center;color:#222;font-size:12px;text-align:center'></div></div><p class='mu' style='font-size:12px'>Ou digite esta chave manualmente no app:</p><p class='mono' style='word-break:break-all;user-select:all;margin:4px 0 10px'>${sec.match(/.{1,4}/g).join(' ')}</p><p class='mu'>2. Digite o código de 6 dígitos que aparece no app.</p><label for='tqc'>Código</label><input id='tqc' inputmode='numeric' maxlength='6' autocomplete='one-time-code'><button class='go full' id='tqg'>Ativar</button><button class='ghost' data-x style='margin-top:10px'>Cancelar</button>`);
 try{new QRCode($('tq'),{text:uri,width:180,height:180,correctLevel:QRCode.CorrectLevel.M})}catch(e){$('tq').textContent='Não foi possível gerar o QR code. Use a chave abaixo.'}
 const go=async()=>{if(!await totpOk(sec,$('tqc').value))return toast('Código incorreto','err');o.remove();done(sec,tag)};$('tqg').onclick=go;$('tqc').onkeydown=e=>{if(e.key==='Enter')go()}}
function totpAsk(u,ok,title){const o=mdl(`<h3>${title}</h3><p class='mu'>Abra o app <b>Google Authenticator</b> e digite o código de 6 dígitos da conta <b>${E(String(SN()).replace(/<[^>]*>/g,''))} (${E(u.n)})</b>.</p><label for='tai'>Código</label><input id='tai' inputmode='numeric' maxlength='6' autocomplete='one-time-code'><button class='go full' id='tag'>Confirmar</button><button class='ghost' data-x style='margin-top:10px'>Cancelar</button>`);setTimeout(()=>$('tai')&&$('tai').focus(),0);const go=async()=>{if(!await totpOk(u.totp,$('tai').value))return toast('Código incorreto ou expirado. Confira se está usando a conta certa no app e tente o próximo código.','err');o.remove();ok()};$('tag').onclick=go;$('tai').onkeydown=e=>{if(e.key==='Enter')go()}}
function tfAsk(u,ok,title){if(u.totp)totpAsk(u,ok,title);else codeM(ok,title,tfVia(u))}
function tfVia(u){const em=String(u.em||'').replace(/^(.).*(@.*)$/,'$1•••$2');return u.tfm==='t'&&u.ph?'o telefone '+phM(u.ph):'o e-mail '+em}
function chCode(ok,title){const u=U(),em=u.em.replace(/^(.).*(@.*)$/,'$1•••$2');const o=mdl(`<h3>${title}</h3><p class='mu'>Escolha onde você quer receber o código de 6 dígitos.</p><div style='display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px'><button type='button' class='cfb' id='chE' style='margin:0;width:100%;height:auto;padding:12px 8px;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center'>${I('mail')} <b>E-mail</b><span class='mu mono' style='font-size:11px;word-break:break-all'>${E(em)}</span></button><button type='button' class='cfb' id='chT' style='margin:0;width:100%;height:auto;padding:12px 8px;flex-direction:column;align-items:center;justify-content:center;gap:4px;text-align:center' ${u.ph?'':'disabled'}>${I('tel')} <b>Telefone (SMS)</b><span class='mu mono' style='font-size:11px'>${u.ph?phM(u.ph):'não cadastrado'}</span></button></div><button class='ghost' data-x style='margin-top:10px'>Cancelar</button>`);$('chE').onclick=()=>{o.remove();codeM(ok,title,'o e-mail '+em,()=>chCode(ok,title))};$('chT').onclick=()=>{if(!u.ph)return;o.remove();codeM(ok,title,'o telefone '+phM(u.ph),()=>chCode(ok,title))}}
function codeM(ok,title,via,back){let c=String(Math.floor(100000+Math.random()*900000));
 const o=mdl(`<div style='display:flex;align-items:center;gap:6px;margin-bottom:6px'>${back?`<button type='button' id='cdb' aria-label='Voltar' style='display:inline-grid;place-items:center;width:32px;height:32px;margin:0 0 0 -8px;flex:none;background:none;border:0;color:var(--mut);cursor:pointer;border-radius:8px;padding:0'><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg></button>`:''}<h3 style='margin:0'>${title}</h3></div><p class='mu'>Enviamos um código de 6 dígitos para ${via||'o seu e-mail'}.</p><p class='hint'>Demonstração: o site não envia mensagens de verdade, então o código aparece aqui: <b class='mono' id='cdc'>${c}</b></p><label for='cdi'>Código</label><input id='cdi' inputmode='numeric' maxlength='6' autocomplete='one-time-code'><button type='button' class='ghost' id='cdr' disabled style='display:block;width:auto;margin:10px auto 0;padding:6px 12px;border:0;background:none;font-size:13px;box-shadow:none'>Reenviar código (30s)</button><button class='go full' id='cdg'>Confirmar</button><button class='ghost' data-x style='margin-top:10px'>Cancelar</button>`);
 setTimeout(()=>$('cdi')&&$('cdi').focus(),0);if(back&&$('cdb'))$('cdb').onclick=()=>{o.remove();back()};
 const go=()=>{if($('cdi').value.trim()!==c)return toast('Código incorreto','err');o.remove();ok()};
 $('cdg').onclick=go;$('cdi').onkeydown=e=>{if(e.key==='Enter')go()};
 let t=30,iv;const tick=()=>{const b=$('cdr');if(!b||!document.body.contains(o)){clearInterval(iv);return}if(t>0){b.disabled=true;b.style.color='';b.textContent='Reenviar código ('+t+'s)';t--}else{clearInterval(iv);b.disabled=false;b.style.color='var(--ac)';b.textContent='Reenviar código'}};tick();iv=setInterval(tick,1000);
 $('cdr').onclick=()=>{c=String(Math.floor(100000+Math.random()*900000));$('cdc').textContent=c;$('cdi').value='';$('cdi').focus();toast('Novo código enviado','good');clearInterval(iv);t=30;tick();iv=setInterval(tick,1000)}}
