function menuEd(eid,isG,pid){const f=eid?menuFind(eid):null,x=f?f.x:{t:'',ic:isG?'list':'link',h:'servicos'},ext=/^https?:\/\//i.test(x.h||'');let ic=P[x.ic]?x.ic:'link';
 const o=mdl(`<h3>${f?'Editar':'Novo'} ${isG?'categoria (com seta)':pid?'item da categoria':'item do menu'}</h3><label for='met'>Nome</label><input id='met' maxlength='30' value='${EA(x.t)}' placeholder='Ex: Promoções' autocomplete='off'>${isG?'':`<label for='meh'>Para onde leva</label><select id='meh'>${PAGES.map(q=>`<option value='${q[0]}' ${!ext&&x.h===q[0]?'selected':''}>${q[1]}</option>`).join('')}<option value='__ext' ${ext?'selected':''}>Link externo (outro site)</option></select><div id='mew' style='display:${ext?'block':'none'}'><label for='meu'>Endereço do link</label><input id='meu' placeholder='https://...' value='${ext?EA(x.h):''}' autocomplete='off'></div>`}<label>Ícone</label><div id='mec' class='tbr' style='gap:6px;margin-bottom:6px'>${ICONS.map(([k,n])=>`<button type='button' class='sm' data-ic='${k}' title='${n}' style='width:40px;height:40px;padding:0;display:grid;place-items:center;font-size:18px'>${I(k)}</button>`).join('')}</div><button class='go full' id='mes'>Salvar</button><button class='ghost' data-x style='margin-top:10px'>Cancelar</button>`);
 const paint=()=>o.querySelectorAll('[data-ic]').forEach(b=>{const on=b.dataset.ic===ic;b.style.borderColor=on?'var(--ac)':'';b.style.background=on?'var(--acd)':'';b.style.color=on?'var(--acl)':''});paint();
 $('mec').onclick=e=>{const b=e.target.closest('[data-ic]');if(!b)return;ic=b.dataset.ic;paint()};
 if($('meh'))$('meh').onchange=e=>{$('mew').style.display=e.target.value==='__ext'?'block':'none'};
 $('mes').onclick=()=>{const t=$('met').value.trim();if(!t)return toast('Digite o nome','err');let h;
  if(!isG){h=$('meh').value;if(h==='__ext'){h=$('meu').value.trim();if(h&&!/^https?:\/\//i.test(h))h='https://'+h;if(!/^https?:\/\/[^\s"'<>]+\.[^\s"'<>]+$/i.test(h))return toast('Digite um link válido. Ex: https://meusite.com','err')}}
  if(f){f.x.t=t;f.x.ic=ic;if(!isG)f.x.h=h}else{const n={id:menuId(),t,ic};if(isG){n.g=1;n.items=[];n.open=1}else n.h=h;if(pid){const g=menuFind(pid);if(!g)return;g.x.items=g.x.items||[];g.x.items.push(n)}else menuAll().push(n)}
  save();o.remove();ceoM();toast('Menu salvo','good')}}
function ceoM(){const m=menuAll();
 const tg=x=>x.g?`Categoria com seta · ${(x.items||[]).length} item(ns)`:(/^https?:\/\//i.test(x.h||'')?'Link externo: '+E(x.h):'Página: '+E((PAGES.find(q=>q[0]===x.h)||[0,x.h])[1]));
 const row=(x,sub,pos,len)=>`<div class='cr' data-id='${x.id}' style='${sub?'margin-left:30px;':''}'><div style='display:flex;align-items:center;gap:12px'><span class='mi2'>${I(P[x.ic]?x.ic:'list')}</span><div><b>${E(x.t)}</b><br><small class='mu'>${tg(x)}</small></div></div>${pos>0?`<button class='sm' data-a='u' title='Subir' aria-label='Subir'>↑</button>`:''}${pos<len-1?`<button class='sm' data-a='d' title='Descer' aria-label='Descer'>↓</button>`:''}<button class='sm' data-a='e'>Editar</button>${x.g?`<button class='sm' data-a='n'>+ Item dentro</button>`:''}<button class='sm' data-a='x' style='color:#e5484d;border-color:rgba(229,72,77,.45)'>Excluir</button></div>`;
 $('adb').innerHTML=`<div class='card bx'><div class='eh'>${I('list')}<b>Menu lateral</b></div><p class='hint' style='margin:0 0 14px'>Adicione, renomeie, reordene ou exclua qualquer item do menu que os clientes veem. Uma <b>categoria com seta</b> (como Saldo &amp; Finanças e Mais) guarda vários itens dentro dela. As mudanças valem assim que você voltar ao site.</p><div class='tbr'><button class='go' id='mni'>+ Novo item</button><button class='sm' id='mng'>+ Nova categoria (com seta)</button><button class='sm' id='mnr'>Restaurar padrão</button></div></div><div class='card bx' style='margin-top:14px' id='mnl'>${m.length?m.map((x,i)=>row(x,0,i,m.length)+(x.g?(x.items||[]).map((y,j)=>row(y,1,j,x.items.length)).join(''):'')).join(''):`<p class='hint'>O menu está vazio. Adicione um item acima.</p>`}</div>`;
 $('mni').onclick=()=>menuEd(null,0);$('mng').onclick=()=>menuEd(null,1);
 $('mnr').onclick=()=>menuAsk('Restaurar o menu para o padrão? Os itens que você criou ou excluiu voltam ao original.',()=>{delete DB.cfg.menu;save();ceoM();toast('Menu restaurado','good')});
 $('mnl').onclick=e=>{const b=e.target.closest('[data-a]'),r=b&&b.closest('[data-id]');if(!r)return;const f=menuFind(r.dataset.id);if(!f)return;const a=b.dataset.a;
  if(a==='u'||a==='d'){const k=f.i+(a==='u'?-1:1);if(k<0||k>=f.a.length)return;[f.a[f.i],f.a[k]]=[f.a[k],f.a[f.i]];save();ceoM()}
  else if(a==='e')menuEd(f.x.id,f.x.g?1:0);
  else if(a==='n')menuEd(null,0,f.x.id);
  else if(a==='x'){const n=f.x.g&&f.x.items&&f.x.items.length;menuAsk(`Excluir <b>${E(f.x.t)}</b>${n?` e os ${n} item(ns) que estão dentro`:''}?`,()=>{f.a.splice(f.i,1);save();ceoM();toast('Item excluído','good')})}}}
