document.addEventListener('click',e=>{const s=$('sd');if(!s)return;if(e.target.closest('#hb')){s.classList.toggle('open');$('bd').classList.toggle('open')}else if(e.target.closest('#bd')||e.target.closest('#sd a')){s.classList.remove('open');$('bd').classList.remove('open')}});addEventListener('keydown',e=>{if(e.key==='Escape')clM()});
