/* ---------- chat assistente (IA) ---------- */
(function(){
const SP='<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l1.9 5.6L19.500 9.500l-5.600 1.900L12 17l-1.900-5.600L4.500 9.500l5.600-1.900z"/><path d="M19 15l.9 2.100L22 18l-2.100.9L19 21l-.9-2.100L16 18l2.100-.9z"/></svg>';
document.body.insertAdjacentHTML("beforeend",`<div id="sfc"><button type="button" class="sfl" id="sfo" aria-label="Abrir assistente" title="Dúvidas? Pergunte"><svg viewBox="0 0 24 24"><path d="M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-5.4A8 8 0 1 1 21 12z"/></svg></button><section class="sfp" role="dialog" aria-label="Assistente SocialFlow"><div class="sfh"><span class="sfa">${SP}<i></i></span><div><b>Assistente SocialFlow<em>IA</em></b><small>Responde na hora · dúvidas sobre o painel</small></div><button type="button" class="sfx" id="sfk" aria-label="Fechar">×</button></div><div class="sfm" id="sfm"></div><div class="sff"><input id="sfi" placeholder="Escreva sua dúvida..." maxlength="300" autocomplete="off" aria-label="Escreva sua dúvida"><button type="button" id="sfs" aria-label="Enviar"><svg viewBox="0 0 24 24"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4z"/></svg></button></div><div class="sfn">Respostas geradas por IA · podem conter erros</div></section></div>`);
const g=id=>document.getElementById(id),box=g("sfc"),m=g("sfm"),inp=g("sfi");
const RULES="Você é o assistente virtual do SocialFlow, um painel de serviços para redes sociais (seguidores, curtidas, visualizações etc.). Responda sempre em português do Brasil, de forma simpática e curta (no máximo 4 frases). Fale só sobre o painel e nunca invente preços, prazos ou promessas. Fatos do painel: para comprar vá em Novo pedido (escolher a rede, a categoria e o serviço, colar o link público do perfil ou post e informar a quantidade); o saldo é adicionado no botão + ao lado do saldo ou em Saldo & Finanças > Adicionar Saldo; o andamento fica em Pedidos; Reembolsos cancela pedidos ainda não finalizados e devolve o valor ao saldo; Cupons e Níveis dão descontos; Afiliados tem link de indicação; existe Transferir Saldo; muitos serviços têm garantia de reposição (veja na descrição do serviço); nunca peça senha. Se não souber ou for um caso individual (pedido ou pagamento específico), peça para abrir um ticket em Tickets. Pergunta do cliente:";
const KB=[
[/(adicion|recarg|deposit|colocar saldo|pix|pagar|pagamento)/,"Para adicionar saldo, clique no botão + ao lado do seu saldo (ou vá em Saldo & Finanças > Adicionar Saldo), escolha o valor e conclua o pagamento. Se pagou e o saldo não apareceu, abra um ticket com o comprovante.",1],
[/(nao chegou|demora|atrasad|parado|nao comecou|status|andamento|cade)/,"Acompanhe o andamento em Pedidos. A maioria dos serviços começa em até 30 minutos, mas a velocidade varia conforme o serviço. Se já passou bastante tempo, abra um ticket com o número do pedido que a equipe verifica.",1],
[/(reembols|cancel|estorn|devolv)/,"Em Reembolsos você cancela pedidos que ainda não foram finalizados, e o valor volta para o seu saldo na hora.",0],
[/(reposic|garantia|caiu|cairam|perdi|diminuiu)/,"Muitos serviços têm garantia de reposição. O prazo aparece na descrição de cada serviço. Se caiu dentro da garantia, abra um ticket com o número do pedido.",1],
[/(cupom|desconto|promo|nivel|nivei)/,"Você tem desconto de duas formas: Níveis (desconto automático conforme o quanto você já gastou) e Cupons (em Saldo & Finanças > Cupons, resgate um código e use no próximo pedido).",0],
[/(afiliad|indica|comissao)/,"Em Afiliados você pega seu link de indicação e acompanha quem entrou por ele.",0],
[/transfer/,"Para enviar saldo para outra pessoa, vá em Saldo & Finanças > Transferir Saldo.",0],
[/(api|revend|integra)/,"A documentação da API fica no menu Mais > API.",0],
[/(link|perfil|privad|publico|senha)/,"Cole o link completo do perfil ou post, por exemplo https://www.instagram.com/usesocialflow/. O perfil precisa estar público e nunca pedimos sua senha.",0],
[/(como (faco|fazer|compro|comprar)|pedido|comprar|novo pedido|servico)/,"Para fazer um pedido: 1) vá em Novo pedido, 2) escolha a rede social, a categoria e o serviço, 3) cole o link, 4) informe a quantidade e clique em Fazer pedido. O valor é descontado do seu saldo.",0],
[/(ticket|suporte|humano|atendente|atendimento|falar com|problema|erro|ajuda)/,"Posso encaminhar você para a equipe. Abra um ticket e descreva o que aconteceu, com o número do pedido se tiver.",1],
[/(oi|ola|bom dia|boa tarde|boa noite|eai|opa)\b/,"Olá! Posso ajudar com pedidos, saldo, reembolsos e tickets. Qual é a sua dúvida?",0]];
const norm=t=>t.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const local=t=>{const n=norm(t),r=KB.find(k=>k[0].test(n));return r?{t:r[1],a:r[2]}:{t:"Não tenho certeza sobre isso. Posso ajudar com pedidos, saldo, reembolsos e garantia. Se for algo específico da sua conta, abra um ticket e a equipe responde por lá.",a:1}};
const add=(t,me)=>{const d=document.createElement("div");d.className="sfb"+(me?" me":"");d.textContent=t;m.appendChild(d);m.scrollTop=m.scrollHeight;return d};
const tk=d=>{const a=document.createElement("a");a.className="sfg";a.href="#tickets";a.textContent="Abrir um ticket";a.onclick=()=>box.classList.remove("open");d.appendChild(a)};
const clean=t=>String(t||"").replace(/\*\*/g,"").replace(/^#+\s*/gm,"").trim();
let ai=null,turns=[],busy=0,greeted=0;
try{if(window.claude&&claude.use)claude.use("sample").then(v=>{if(typeof v==="function")ai=v}).catch(()=>{})}catch(e){}
async function send(txt){txt=txt.trim();if(!txt||busy)return;busy=1;const q=m.querySelector(".sfq");if(q)q.remove();add(txt,1);inp.value="";
 const b=add("Digitando...");b.classList.add("ty");let out=null;
 if(ai){try{const h=turns.slice(-6).concat([{role:"user",content:txt}]);h[0]={role:"user",content:RULES+"\n\n"+h[0].content};
  const r=await ai(h,{cache:false,modelTier:"quick",onText:({text})=>{b.classList.remove("ty");b.textContent=clean(text);m.scrollTop=m.scrollHeight}});out=clean(r.text)}catch(e){if(e&&e.code==="not_granted")ai=null;out=null}}
 let a=0;if(out){a=/ticket/i.test(out)}else{const r=local(txt);out=r.t;a=r.a}
 b.classList.remove("ty");b.textContent=out;if(a)tk(b);m.scrollTop=m.scrollHeight;
 turns.push({role:"user",content:txt},{role:"assistant",content:out});busy=0}
function open(){box.classList.add("open");if(!greeted){greeted=1;add("Oi! Sou o assistente do SocialFlow. Posso ajudar com pedidos, saldo, reembolsos e tickets. O que você precisa?");const q=document.createElement("div");q.className="sfq";["Como faço um pedido?","Como adiciono saldo?","Meu pedido não chegou","Falar com o suporte"].forEach(t=>{const b=document.createElement("button");b.type="button";b.textContent=t;b.onclick=()=>send(t);q.appendChild(b)});m.appendChild(q)}setTimeout(()=>inp.focus(),50)}
g("sfo").onclick=open;g("sfk").onclick=()=>box.classList.remove("open");g("sfs").onclick=()=>send(inp.value);
inp.onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();send(inp.value)}};
addEventListener("keydown",e=>{if(e.key==="Escape")box.classList.remove("open")});
const vis=()=>{const h=location.hash.slice(1);box.style.display=(h==="ceo"||h==="admin")?"none":""};vis();addEventListener("hashchange",vis);
})();
